def forward(groups):
    size_value, size_unit = float(groups[2]), groups[4]
    free_value, free_unit = float(groups[8]), groups[10]
    scale = {'B': 1, 'KB': 1024, 'GB': 1024 ** 3, 'MB': 1024 ** 2}
    size_canonical = int(size_value * scale[size_unit])
    free_canonical = int(free_value * scale[free_unit])
    return {'stored': [size_canonical, free_canonical], 'layout': [size_unit, free_unit]}

def inverse(record):
    size_canonical, free_canonical = record['stored']
    size_unit, free_unit = record['layout']
    scale = {'B': 1, 'KB': 1024, 'GB': 1024 ** 3, 'MB': 1024 ** 2}
    size_value = size_canonical / scale[size_unit]
    free_value = free_canonical / scale[free_unit]
    return f"size: {size_value:.1f} {size_unit}, free: {free_value:.1f} {free_unit}"
